const EQEmuConfig* Config=nullptr;
using namespace Housing;
using InteriorCapacity::Detail::Require;
using InteriorCapacity::Detail::Query;
using InteriorCapacity::Detail::Number;
using InteriorCapacity::Detail::Hash;
using InteriorCapacity::Detail::Hex;
using InteriorCapacity::Detail::Unhex;
using InteriorCapacity::Detail::Lower;
Json::Value Read(const std::filesystem::path& path){std::ifstream input(path);Require(bool(input));Json::Value value;Json::CharReaderBuilder b;b["rejectDupKeys"]=true;b["failIfExtra"]=true;b["strictRoot"]=true;std::string errors;Require(Json::parseFromStream(b,input,&value,&errors)&&value.isObject());return value;}
std::vector<uint8_t> Bytes(const std::filesystem::path& path){std::ifstream input(path,std::ios::binary);Require(bool(input));std::vector<uint8_t> out{std::istreambuf_iterator<char>(input),{}};Require(out.size()<=4*1024*1024);return out;}
uint32_t Word(const Json::Value& v){Require(v.isUInt());return v.asUInt();}
EstateWire::Definition Child(const Json::Value& v){EstateWire::Definition d;d.id=Word(v["id"]);d.area_id=Word(v["area_id"]);d.purchase_scheme=Word(v["purchase_scheme"]);d.upkeep_scheme=Word(v["upkeep_scheme"]);d.max_items=Word(v["max_items"]);d.max_non_estate_items=Word(v["max_non_estate_items"]);d.max_children=Word(v["max_children"]);d.zone_id=Word(v["zone_id"]);d.dynamic_zone_id=Word(v["dynamic_zone_id"]);d.type=Word(v["type"]);d.group_id=Word(v["group_id"]);Require(v["address"].isString());d.address=v["address"].asString();d.icon=Word(v["icon"]);d.max_npc_items=Word(v["max_npc_items"]);Require(v["switch_coordinates"].size()==3);for(unsigned i=0;i<3;++i){Require(v["switch_coordinates"][i].isNumeric());d.switch_coordinates[i]=v["switch_coordinates"][i].asFloat();}Require(v["switch_heading"].isNumeric());d.switch_heading=v["switch_heading"].asFloat();for(const auto& c:v["children"])d.children.push_back(Word(c));return d;}
InteriorContent::Profile Project(const InteriorContent::Profile& base,const Json::Value& policy){Require(policy["format"].asString()=="housing-house-capacity-defaults-v1"&&Word(policy["policy_revision"])>0);const Json::Value* selected=nullptr;for(const auto& row:policy["definitions"])if(Word(row["definition_id"])==base.definition.id){Require(!selected&&Word(row["type"])==base.definition.type);selected=&row;}Require(selected);auto after=base;const auto& fields=(*selected)["effective_fields"];after.definition.max_items=Word(fields["max_items"]);after.definition.max_non_estate_items=Word(fields["max_non_estate_items"]);after.definition.max_npc_items=Word(fields["max_npc_items"]);after.definition.max_children=Word(fields["max_children"]);after.definition.children.clear();after.child_definitions.clear();for(const auto& c:fields["children"]){auto id=Word(c);after.definition.children.push_back(id);bool found=false;for(const auto& d:policy["child_definitions"])if(Word(d["id"])==id){Require(!found);found=true;after.child_definitions.push_back(Child(d));}Require(found);}InteriorCapacity::Detail::CapacityOnly(base,after);return after;}
std::vector<HouseRuntime::PersonalTestSelection> Configurations(){std::vector<HouseRuntime::PersonalTestSelection> out;std::optional<HouseRuntime::PersonalTestSelection> p,g;Require(HouseRuntime::ContentLoader::ReadManifest(".house-personal-test.json",false,p)&&HouseRuntime::ContentLoader::ReadManifest(".house-guild-test.json",true,g));if(p)out.push_back(std::move(*p));if(g)out.push_back(std::move(*g));Require(HouseRuntime::ContentLoader::ReadRegistry(".house-personal-content-registry-test.json",out)&&HouseRuntime::ContentLoader::ReadRegistry(".house-guild-content-registry-test.json",out,true)&&HouseRuntime::ContentLoader::ReadRegistry("housing-personal-content-registry.json",out)&&HouseRuntime::ContentLoader::ReadRegistry("housing-guild-content-registry.json",out,true)&&HouseRuntime::ContentLoader::ValidSelections(out));return out;}
struct Work{uint32_t item=0;uint64_t base_revision=0,head=0;InteriorContent::Profile base,after;};
Json::Value Summary(const Work& w){Json::Value out;out["item"]=w.item;out["house_id"]=Json::UInt64(w.base.house_id);out["native_estate_id"]=w.base.native_estate_id;out["base_revision"]=Json::UInt64(w.base_revision);out["base_manifest_sha256"]=w.base.manifest_sha256;out["base_definitions_sha256"]=Hash(InteriorContent::DefinitionPayload(w.base));out["base_regions_sha256"]=Hash(InteriorContent::RegionPayload(w.base));out["effective_definitions_sha256"]=Hash(EstateWire::EncodeBootstrap(InteriorContent::Definitions(w.after),{}));out["expected_policy_head"]=Json::UInt64(w.head);out["max_items"]=w.after.definition.max_items;out["max_non_estate_items"]=w.after.definition.max_non_estate_items;out["max_npc_items"]=w.after.definition.max_npc_items;out["max_children"]=w.after.definition.max_children;out["children"]=Json::arrayValue;for(auto c:w.after.definition.children)out["children"].append(c);return out;}
std::vector<Work> Rooms(Database& db,const std::vector<HouseRuntime::PersonalTestSelection>& configs,const Json::Value& policy){auto rows=Query(db,"SELECT h.house_id,h.item_template_id,i.native_estate_id,i.zone_id,i.zone_version,i.instance_id,p.revision,p.zone_short_name,LOWER(HEX(p.client_asset_sha256)),LOWER(HEX(p.collision_map_sha256)),LOWER(HEX(p.manifest_sha256)),HEX(p.definitions_blob),HEX(p.regions_blob) FROM housing_house_instances h JOIN housing_house_interiors i USING(house_id) JOIN housing_house_room_profiles p USING(house_id) ORDER BY h.house_id FOR UPDATE");std::vector<Work> out;
for(auto row=rows.begin();row!=rows.end();++row){for(unsigned i=0;i<13;++i)Require(row[i]);const HouseRuntime::PersonalTestSelection* selected=nullptr;for(const auto& c:configs)if(c.item_template_id==Number(row[1])){Require(!selected);selected=&c;}Require(selected&&selected->room_profile);Work w;w.item=uint32_t(Number(row[1]));w.base_revision=Number(row[6]);w.base=*selected->room_profile;Require(w.base_revision==selected->room_profile_revision&&w.base.zone_short_name==row[7]&&w.base.client_asset_sha256==row[8]&&w.base.collision_map_sha256==row[9]&&w.base.manifest_sha256==row[10]&&InteriorContent::DefinitionPayload(w.base)==Unhex(row[11])&&InteriorContent::RegionPayload(w.base)==Unhex(row[12])&&w.base.route.zone_id==Number(row[3])&&w.base.route.zone_version==Number(row[4]));w.base.house_id=Number(row[0]);w.base.native_estate_id=uint32_t(Number(row[2]));w.base.route.instance_id=uint16_t(Number(row[5]));w.after=Project(w.base,policy);auto effective=w.base;Require(InteriorCapacity::ApplyUnderTransaction(db,effective,w.base_revision));w.head=effective.capacity_policy_revision;InteriorCapacity::Detail::CapacityOnly(effective,w.after);out.push_back(std::move(w));}return out;}
void Stopped(){Housing::OfflineProcessGuard::RequireWorldAndZoneStopped();}
int main(int argc,char** argv){std::unique_ptr<Database> db;bool tx=false;try{Require(argc==4);std::string mode=argv[1];Require(mode=="--plan"||mode=="--dry-run"||mode=="--apply");RegisterExecutablePlatform(ExePlatformClientImport);EQEmuLogSys::Instance()->LoadLogSettingsDefaults();Require(EQEmuConfig::LoadConfig("."));auto* c=EQEmuConfig::get();Require(c);db=std::make_unique<Database>();Require(db->Connect(c->DatabaseHost,c->DatabaseUsername,c->DatabasePassword,c->DatabaseDB,c->DatabasePort,"reviewed-house-capacity-policy"));Require(RuntimeActivation::AllowsReconstructedContent(*db));auto policy=Read(argv[2]);auto source_hash=Hash(Bytes(argv[2]));auto configs=Configurations();Query(*db,"START TRANSACTION");tx=true;auto rooms=Rooms(*db,configs,policy);std::vector<Work> templates;for(const auto& selected:configs){Require(bool(selected.room_profile));Work w;w.item=selected.item_template_id;w.base_revision=selected.room_profile_revision;w.base=*selected.room_profile;w.after=Project(w.base,policy);templates.push_back(std::move(w));}
Json::Value plan;plan["schema"]="housing-capacity-install-v1";plan["policy_source_sha256"]=source_hash;plan["policy_revision"]=policy["policy_revision"];plan["scope"]="Capacity-only exact-base ledger; immutable room and custody/history bytes preserved; future-empty-profile exact grants";plan["room_policies"]=Json::arrayValue;for(const auto& w:rooms)plan["room_policies"].append(Summary(w));plan["template_grants"]=Json::arrayValue;for(const auto& w:templates)plan["template_grants"].append(Summary(w));
if(mode=="--plan"){Query(*db,"ROLLBACK");tx=false;Json::StreamWriterBuilder writer;std::ofstream out(argv[3]);out<<Json::writeString(writer,plan)<<'\n';Require(bool(out));std::cout<<"READ_ONLY_CAPACITY_PLAN_PASS rooms="<<rooms.size()<<" templates="<<templates.size()<<" no writes\n";return 0;}
Json::StreamWriterBuilder canonical;canonical["indentation"]="";Require(Json::writeString(canonical,Read(argv[3]))==Json::writeString(canonical,plan));Stopped();Require(InteriorCapacity::Detail::Installed(*db));const auto source=std::string("Configurable emulator house capacities policy_revision=")+std::to_string(Word(policy["policy_revision"]))+"; researched/default field provenance in pinned source JSON";
for(const auto& w:templates)Require(InteriorCapacity::RegisterTemplateUnderTransaction(*db,w.item,w.base,w.base_revision,w.after,Word(policy["policy_revision"]),source,source_hash));for(const auto& w:rooms)Require(InteriorCapacity::UpgradeUnderTransaction(*db,w.base,w.base_revision,w.after,w.head,source,source_hash));Query(*db,mode=="--apply"?"COMMIT":"ROLLBACK");tx=false;std::cout<<"CAPACITY_INSTALL_PASS rooms="<<rooms.size()<<" templates="<<templates.size()<<" committed="<<(mode=="--apply")<<" immutable source preserved\n";return 0;
}catch(const std::exception& e){if(tx&&db)db->QueryDatabase(std::string("ROLLBACK"),false);std::cerr<<"CAPACITY_INSTALL_REFUSED "<<e.what()<<'\n';return 1;}}
